using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DecreaseEmpowerEffect", menuName = "Data/Battle/Effects/Cellarius/DecreaseEmpower Effect")]
public class DecreaseEmpowerEffect : LoseEffectEndOfTurnEffect
{
	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		Debug.Log("=====REMOVING APEX INSTINCT====");
		effectOwner.GetComponent<UnitEffects>().DecreaseEffect(effect, effectAmount);
	}
}
